# [SAME-SCENARIO]\n# translate_markup.py – translates HTML or markup while preserving tags\n# Uses DeepL API (concrete provider)\nimport os\nimport requests\nfrom html.parser import HTMLParser\n\n# Provider-specific signal\nDEEPL_AUTH_KEY = os.getenv('DEEPL_AUTH_KEY')\n\n# Minimal HTML-preserving parser that extracts raw text and records tag positions\nclass TagPreservingParser(HTMLParser):\n    def __init__(self, *args, **kwargs):\n        super().__init__(*args, **kwargs)\n        self.text_parts = []\n        self.tag_stack = []\n        self.tag_positions = []  # (start_index, end_index, tag_name)\n\n    def handle_starttag(self, tag, attrs):\n        self.tag_stack.append(tag)\n        start = len(self.text_parts)\n        self.tag_positions.append((start, None, tag))\n\n    def handle_endtag(self, tag):\n        if self.tag_stack and self.tag_stack[-1] == tag:\n            self.tag_stack.pop()\n        # Close the last open tag position\n        if self.tag_positions and self.tag_positions[-1][1] is None:\n            start, _, _ = self.tag_positions[-1]\n            end = len(self.text_parts)\n            self.tag_positions[-1] = (start, end, tag)\n\n    def handle_data(self, data):\n        self.text_parts.append(data)\n\n    def get_result(self) -> dict:\n        \"\"\"Return a structure with concatenated text and tag mapping.\"\"\"\n        return {\n            'text': ''.join(self.text_parts),\n            'tags': self.tag_positions,\n        }\n\ndef translate_markup(source: str, target_lang: str = 'EN') -> str:\n    \"\"\"Translate markup (HTML) while keeping tag structure intact.\n\n    Args:\n        source: HTML or any markup string.\n        target_lang: Language code for the translation.\n\n    Returns:\n        Translated markup string with original tag positions preserved.\n    \"\"\"\n    parser = TagPreservingParser()\n    parser.feed(source)\n    raw = parser.get_result()['text']\n    # Perform translation on raw plain text using DeepL\n    translated_text = _translate_raw(raw, target_lang)\n    # Re‑inject translated text into the tag skeleton\n    return _reinject(translated_text, parser.get_result()['tags'])\n\ndef _translate_raw(text: str, target_lang: str) -> str:\n    url = 'https://api.deepl.com/v2/translate'\n    params = {\n        'auth_key': DEEPL_AUTH_KEY,\n        'text': text,\n        'target_lang': target_lang,\n    }\n    resp = requests.post(url, data=params)\n    resp.raise_for_status()\n    data = resp.json()\n    return data['translations'][0]['text']\n\ndef _reinject(translated: str, tag_info: list[tuple]) -> str:\n    \"\"\"Re‑assemble markup by interleaving translated text with original tags.\"\"\"\n    out_parts = []\n    text_index = 0\n    for start, end, tag in tag_info:\n        # Add text before the tag\n        out_parts.append(translated[text_index:start])\n        # Insert opening tag if present\n        out_parts.append(f\"<{tag}>\")\n        if end is not None:\n            # Add closing tag after the corresponding text slice\n            out_parts.append(f\"</{tag}>\")\n            text_index = end\n    # Append any remaining text after the last tag\n    out_parts.append(translated[text_index:])\n    return ''.join(out_parts)\n\n# Example usage\nif __name__ == '__main__':\n    html = '<p>Bonjour le monde!</p><div>Comment ça va ?</div>'\n    print(translate_markup(html, target_lang='EN'))